-- ----------------------------------------------------------------------------
-- Users: Login identities for the demo (stub auth).
-- ----------------------------------------------------------------------------
CREATE TABLE users (
  user_id                             TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  email                               TEXT                ,
  role                                TEXT                ,                     -- trainer | client | admin
  display_name                        TEXT                
);
COMMENT ON TABLE users IS 'Login identities for the demo (stub auth).';
COMMENT ON COLUMN users.role IS 'trainer | client | admin';

-- ----------------------------------------------------------------------------
-- Trainers: Personal trainers who log sessions and bill clients.
-- ----------------------------------------------------------------------------
CREATE TABLE trainers (
  trainer_id                          TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  email                               TEXT                ,
  full_name                           TEXT                ,
  hourly_rate                         NUMERIC                                   -- Default $/hour charged to clients.
);
COMMENT ON TABLE trainers IS 'Personal trainers who log sessions and bill clients.';
COMMENT ON COLUMN trainers.hourly_rate IS 'Default $/hour charged to clients.';

-- ----------------------------------------------------------------------------
-- Clients: Trainer's clients.
-- ----------------------------------------------------------------------------
CREATE TABLE clients (
  client_id                           TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  email                               TEXT                ,
  full_name                           TEXT                ,
  trainer                             TEXT                
);
COMMENT ON TABLE clients IS 'Trainer''s clients.';

-- ----------------------------------------------------------------------------
-- Invoices: An invoice bundles one or more sessions billed to a client.
-- ----------------------------------------------------------------------------
CREATE TABLE invoices (
  invoice_id                          TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  client                              TEXT                ,
  issue_date                          TIMESTAMPTZ         ,
  due_date                            TIMESTAMPTZ         ,
  tax_rate                            NUMERIC             ,                     -- Decimal (e.g. 0.08 = 8%).
  discount_amount                     NUMERIC             ,
  paid_amount                         NUMERIC             
);
COMMENT ON TABLE invoices IS 'An invoice bundles one or more sessions billed to a client.';
COMMENT ON COLUMN invoices.tax_rate IS 'Decimal (e.g. 0.08 = 8%).';

-- ----------------------------------------------------------------------------
-- Sessions: A logged training session. The atomic line item that rolls up into an invoice.
-- ----------------------------------------------------------------------------
CREATE TABLE sessions (
  session_id                          TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  client                              TEXT                ,
  session_date                        TIMESTAMPTZ         ,
  duration_hours                      NUMERIC             ,
  rate_override                       NUMERIC             ,                     -- If > 0, overrides the trainer's HourlyRate for this session.
  notes                               TEXT                ,
  invoice                             TEXT                
);
COMMENT ON TABLE sessions IS 'A logged training session. The atomic line item that rolls up into an invoice.';
COMMENT ON COLUMN sessions.rate_override IS 'If > 0, overrides the trainer''s HourlyRate for this session.';

