-- calc_sessions_invoice_name
-- Field: Sessions.InvoiceName
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Name from related Invoices

CREATE OR REPLACE FUNCTION calc_sessions_invoice_name(p_session_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT name::text FROM invoices WHERE invoice_id = (SELECT invoice FROM sessions WHERE session_id = p_session_id));
$$ LANGUAGE sql STABLE;

-- get_invoices_name
-- Helper function: Get Name from Invoices by InvoiceId
-- Used for join-free cross-table references in aggregations
CREATE OR REPLACE FUNCTION get_invoices_name(p_invoice_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT name FROM invoices WHERE invoice_id = p_invoice_id);
$$ LANGUAGE sql STABLE;

