RETURNS TIMESTAMPTZ AS $$
  SELECT (SELECT issue_date FROM invoices WHERE invoice_id = p_invoice_id);
$$ LANGUAGE sql STABLE;

-- get_invoices_due_date
-- Helper function: Get DueDate from Invoices by InvoiceId
-- Used for join-free cross-table references in aggregations
CREATE OR REPLACE FUNCTION get_invoices_due_date(p_invoice_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT (SELECT due_date FROM invoices WHERE invoice_id = p_invoice_id);
$$ LANGUAGE sql STABLE;

-- get_invoices_tax_rate
-- Helper function: Get TaxRate from Invoices by InvoiceId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_invoices_tax_rate(p_invoice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (SELECT tax_rate FROM invoices WHERE invoice_id = p_invoice_id);
$$ LANGUAGE sql STABLE;

-- get_invoices_discount_amount
-- Helper function: Get DiscountAmount from Invoices by InvoiceId
-- Used for join-free cross-table references in aggregations
CREATE OR REPLACE FUNCTION get_invoices_discount_amount(p_invoice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (SELECT discount_amount FROM invoices WHERE invoice_id = p_invoice_id);
$$ LANGUAGE sql STABLE;

-- get_invoices_paid_amount
-- Helper function: Get PaidAmount from Invoices by InvoiceId
-- Used for join-free cross-table references in aggregations
CREATE OR REPLACE FUNCTION get_invoices_paid_amount(p_invoice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (SELECT paid_amount FROM invoices WHERE invoice_id = p_invoice_id);
$$ LANGUAGE sql STABLE;

-- calc_sessions_effective_rate
-- Field: Sessions.EffectiveRate
-- Type: calculated | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_sessions_effective_rate(p_session_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN ((SELECT rate_override FROM sessions WHERE session_id = p_session_id))::NUMERIC > 0 THEN ((SELECT rate_override FROM sessions WHERE session_id = p_session_id))::text ELSE (calc_sessions_client_hourly_rate(p_session_id))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_sessions_line_total
-- Field: Sessions.LineTotal
-- Type: calculated | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_sessions_line_total(p_session_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_sessions_effective_rate(p_session_id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT duration_hours FROM sessions WHERE session_id = p_session_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_sessions_is_billed
-- Field: Sessions.IsBilled
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_sessions_is_billed(p_session_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (NOT ((((SELECT NULLIF(invoice, '') FROM sessions WHERE session_id = p_session_id)) IS NULL OR ((SELECT NULLIF(invoice, '') FROM sessions WHERE session_id = p_session_id))::text = '')))::boolean;
$$ LANGUAGE sql STABLE;

